-- JMS initial schema.
--
-- Conventions:
--   * UUID text primary keys generated by the application.
--   * UTC ISO-8601 text timestamps; ISO strings sort chronologically.
--   * Money is integer pence. Quantities are integer thousandths.
--   * Booleans are integers constrained to 0/1.
--   * Enumerations are TEXT + CHECK so bad data cannot be inserted even by a
--     maintenance script.
--   * Mutable business records carry `version` for optimistic concurrency.

PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS schema_migrations (
  version    INTEGER PRIMARY KEY,
  name       TEXT NOT NULL,
  checksum   TEXT NOT NULL,
  applied_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS companies (
  id                  TEXT PRIMARY KEY,
  name                TEXT NOT NULL,
  trading_name        TEXT,
  email               TEXT NOT NULL,
  phone               TEXT NOT NULL,
  address_line1       TEXT NOT NULL,
  address_line2       TEXT,
  address_town        TEXT NOT NULL,
  address_postcode    TEXT NOT NULL,
  address_country     TEXT NOT NULL DEFAULT 'GB',
  vat_number          TEXT,
  logo_path           TEXT,
  currency            TEXT NOT NULL DEFAULT 'GBP',
  timezone            TEXT NOT NULL DEFAULT 'Europe/London',
  default_theme_json  TEXT NOT NULL DEFAULT '{}',
  invoice_due_days    INTEGER NOT NULL DEFAULT 14 CHECK (invoice_due_days BETWEEN 0 AND 365),
  pdf_footer          TEXT NOT NULL DEFAULT '',
  version             INTEGER NOT NULL DEFAULT 1,
  created_at          TEXT NOT NULL,
  updated_at          TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS roles (
  key         TEXT PRIMARY KEY CHECK (key IN ('ADMIN','MANAGER','ENGINEER','CUSTOMER')),
  label       TEXT NOT NULL,
  description TEXT NOT NULL,
  is_system   INTEGER NOT NULL DEFAULT 1 CHECK (is_system IN (0,1)),
  sort_order  INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS permissions (
  role_key   TEXT NOT NULL REFERENCES roles(key),
  action_key TEXT NOT NULL,
  allowed    INTEGER NOT NULL DEFAULT 0 CHECK (allowed IN (0,1)),
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL,
  PRIMARY KEY (role_key, action_key)
);

CREATE TABLE IF NOT EXISTS customers (
  id               TEXT PRIMARY KEY,
  company_id       TEXT NOT NULL REFERENCES companies(id),
  name             TEXT NOT NULL COLLATE NOCASE,
  contact_name     TEXT NOT NULL,
  email            TEXT NOT NULL COLLATE NOCASE,
  phone            TEXT NOT NULL,
  address_line1    TEXT NOT NULL,
  address_line2    TEXT,
  address_town     TEXT NOT NULL,
  address_postcode TEXT NOT NULL,
  address_country  TEXT NOT NULL DEFAULT 'GB',
  notes            TEXT,
  status           TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','ARCHIVED')),
  version          INTEGER NOT NULL DEFAULT 1,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL,
  created_by       TEXT NOT NULL,
  archived_at      TEXT,
  UNIQUE (company_id, name),
  UNIQUE (company_id, email)
);

CREATE TABLE IF NOT EXISTS users (
  id                   TEXT PRIMARY KEY,
  company_id           TEXT NOT NULL REFERENCES companies(id),
  email                TEXT NOT NULL COLLATE NOCASE UNIQUE,
  password_hash        TEXT NOT NULL,
  display_name         TEXT NOT NULL,
  role_key             TEXT NOT NULL REFERENCES roles(key),
  customer_id          TEXT REFERENCES customers(id),
  can_engineer         INTEGER NOT NULL DEFAULT 0 CHECK (can_engineer IN (0,1)),
  phone                TEXT,
  status               TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('INVITED','ACTIVE','SUSPENDED','ARCHIVED')),
  must_change_password INTEGER NOT NULL DEFAULT 1 CHECK (must_change_password IN (0,1)),
  theme_prefs_json     TEXT,
  last_login_at        TEXT,
  version              INTEGER NOT NULL DEFAULT 1,
  created_at           TEXT NOT NULL,
  updated_at           TEXT NOT NULL,
  CHECK ((role_key = 'CUSTOMER' AND customer_id IS NOT NULL) OR (role_key <> 'CUSTOMER' AND customer_id IS NULL)),
  CHECK (role_key <> 'ADMIN' OR can_engineer = 0),
  CHECK (role_key <> 'ENGINEER' OR can_engineer = 1)
);

CREATE TABLE IF NOT EXISTS sessions (
  id_hash              TEXT PRIMARY KEY,
  user_id              TEXT NOT NULL REFERENCES users(id),
  csrf_token           TEXT NOT NULL,
  created_at           TEXT NOT NULL,
  last_seen_at         TEXT NOT NULL,
  expires_at           TEXT NOT NULL,
  absolute_expires_at  TEXT NOT NULL,
  revoked_at           TEXT,
  ip                   TEXT,
  user_agent           TEXT,
  flash_json           TEXT
);
CREATE INDEX IF NOT EXISTS sessions_user_ix ON sessions(user_id);
CREATE INDEX IF NOT EXISTS sessions_expiry_ix ON sessions(expires_at);

CREATE TABLE IF NOT EXISTS jobs (
  id                TEXT PRIMARY KEY,
  company_id        TEXT NOT NULL REFERENCES companies(id),
  reference         TEXT NOT NULL UNIQUE,
  customer_id       TEXT NOT NULL REFERENCES customers(id),
  title             TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 140),
  description       TEXT NOT NULL,
  work_type         TEXT NOT NULL CHECK (work_type IN ('WINDOW_INSTALL','REPAIR','SURVEY')),
  status            TEXT NOT NULL CHECK (status IN ('DRAFT','SCHEDULED','IN_PROGRESS','ON_HOLD','COMPLETED','INVOICED','PAID','CANCELLED')),
  priority          TEXT NOT NULL DEFAULT 'NORMAL' CHECK (priority IN ('NORMAL','URGENT')),
  site_line1        TEXT NOT NULL,
  site_line2        TEXT,
  site_town         TEXT NOT NULL,
  site_postcode     TEXT NOT NULL,
  site_country      TEXT NOT NULL DEFAULT 'GB',
  planned_start     TEXT,
  planned_end       TEXT,
  planned_slot      TEXT NOT NULL DEFAULT 'ALL_DAY' CHECK (planned_slot IN ('AM','PM','ALL_DAY')),
  actual_start      TEXT,
  actual_end        TEXT,
  price_net         INTEGER CHECK (price_net IS NULL OR price_net >= 0),
  vat_rate_bp       INTEGER NOT NULL DEFAULT 2000 CHECK (vat_rate_bp BETWEEN 0 AND 10000),
  price_gross       INTEGER CHECK (price_gross IS NULL OR price_gross >= 0),
  internal_notes    TEXT,
  customer_notes    TEXT,
  version           INTEGER NOT NULL DEFAULT 1,
  created_by        TEXT NOT NULL REFERENCES users(id),
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  archived_at       TEXT,
  CHECK (planned_end IS NULL OR planned_start IS NULL OR planned_end >= planned_start)
);
CREATE INDEX IF NOT EXISTS jobs_customer_status_ix ON jobs(customer_id, status);
CREATE INDEX IF NOT EXISTS jobs_status_start_ix ON jobs(status, planned_start);
CREATE INDEX IF NOT EXISTS jobs_planned_ix ON jobs(planned_start);

CREATE TABLE IF NOT EXISTS job_assignments (
  id          TEXT PRIMARY KEY,
  job_id      TEXT NOT NULL REFERENCES jobs(id),
  user_id     TEXT NOT NULL REFERENCES users(id),
  is_lead     INTEGER NOT NULL DEFAULT 0 CHECK (is_lead IN (0,1)),
  assigned_at TEXT NOT NULL,
  assigned_by TEXT NOT NULL REFERENCES users(id),
  removed_at  TEXT
);
CREATE INDEX IF NOT EXISTS assignments_job_active_ix ON job_assignments(job_id) WHERE removed_at IS NULL;
CREATE INDEX IF NOT EXISTS assignments_user_ix ON job_assignments(user_id, removed_at);
CREATE UNIQUE INDEX IF NOT EXISTS assignments_one_active_ix
  ON job_assignments(job_id, user_id) WHERE removed_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS assignments_one_lead_ix
  ON job_assignments(job_id) WHERE is_lead = 1 AND removed_at IS NULL;

CREATE TABLE IF NOT EXISTS job_events (
  id            TEXT PRIMARY KEY,
  job_id        TEXT NOT NULL REFERENCES jobs(id),
  actor_user_id TEXT NOT NULL REFERENCES users(id),
  type          TEXT NOT NULL CHECK (type IN ('STATUS_CHANGE','ASSIGNMENT','SCHEDULE_CHANGE','NOTE','DOCUMENT','PRICE_CHANGE','CREATED','ARCHIVED')),
  from_value    TEXT,
  to_value      TEXT,
  message       TEXT,
  visibility    TEXT NOT NULL CHECK (visibility IN ('INTERNAL','CUSTOMER')),
  at            TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS job_events_job_ix ON job_events(job_id, at);

CREATE TABLE IF NOT EXISTS invoices (
  id            TEXT PRIMARY KEY,
  company_id    TEXT NOT NULL REFERENCES companies(id),
  number        TEXT NOT NULL UNIQUE,
  job_id        TEXT NOT NULL REFERENCES jobs(id),
  status        TEXT NOT NULL CHECK (status IN ('DRAFT','ISSUED','PAID','VOID')),
  issued_at     TEXT,
  due_at        TEXT,
  paid_at       TEXT,
  net           INTEGER NOT NULL CHECK (net >= 0),
  vat_rate_bp   INTEGER NOT NULL CHECK (vat_rate_bp BETWEEN 0 AND 10000),
  vat           INTEGER NOT NULL CHECK (vat >= 0),
  gross         INTEGER NOT NULL CHECK (gross >= 0),
  notes         TEXT,
  version       INTEGER NOT NULL DEFAULT 1,
  created_by    TEXT NOT NULL REFERENCES users(id),
  created_at    TEXT NOT NULL,
  voided_at     TEXT,
  void_reason   TEXT,
  CHECK (gross = net + vat)
);
CREATE INDEX IF NOT EXISTS invoices_job_ix ON invoices(job_id);
CREATE INDEX IF NOT EXISTS invoices_status_ix ON invoices(status, issued_at);
CREATE UNIQUE INDEX IF NOT EXISTS invoices_one_live_ix ON invoices(job_id) WHERE status <> 'VOID';

CREATE TABLE IF NOT EXISTS invoice_lines (
  id           TEXT PRIMARY KEY,
  invoice_id   TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
  line_no      INTEGER NOT NULL,
  description  TEXT NOT NULL,
  qty_milli    INTEGER NOT NULL CHECK (qty_milli > 0),
  unit_pence   INTEGER NOT NULL CHECK (unit_pence >= 0),
  amount_pence INTEGER NOT NULL CHECK (amount_pence >= 0),
  UNIQUE (invoice_id, line_no)
);

CREATE TABLE IF NOT EXISTS documents (
  id           TEXT PRIMARY KEY,
  type         TEXT NOT NULL CHECK (type IN ('JOB_SHEET','INVOICE')),
  entity_type  TEXT NOT NULL CHECK (entity_type IN ('JOB','INVOICE')),
  entity_id    TEXT NOT NULL,
  version      INTEGER NOT NULL,
  generated_at TEXT NOT NULL,
  generated_by TEXT NOT NULL REFERENCES users(id),
  file_path    TEXT NOT NULL,
  checksum     TEXT NOT NULL,
  size_bytes   INTEGER NOT NULL CHECK (size_bytes >= 0),
  mime         TEXT NOT NULL DEFAULT 'application/pdf'
);
CREATE INDEX IF NOT EXISTS documents_entity_ix ON documents(entity_type, entity_id, version);

CREATE TABLE IF NOT EXISTS settings (
  key        TEXT PRIMARY KEY,
  value_json TEXT NOT NULL,
  version    INTEGER NOT NULL DEFAULT 1,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS audit_log (
  id            TEXT PRIMARY KEY,
  company_id    TEXT NOT NULL REFERENCES companies(id),
  actor_user_id TEXT REFERENCES users(id),
  action        TEXT NOT NULL,
  entity_type   TEXT NOT NULL,
  entity_id     TEXT,
  before_json   TEXT,
  after_json    TEXT,
  at            TEXT NOT NULL,
  ip            TEXT,
  user_agent    TEXT,
  request_id    TEXT
);
CREATE INDEX IF NOT EXISTS audit_at_ix ON audit_log(at);
CREATE INDEX IF NOT EXISTS audit_entity_ix ON audit_log(entity_type, entity_id);

CREATE TABLE IF NOT EXISTS sequences (
  kind  TEXT NOT NULL CHECK (kind IN ('job','invoice')),
  year  INTEGER NOT NULL,
  value INTEGER NOT NULL DEFAULT 0 CHECK (value >= 0),
  PRIMARY KEY (kind, year)
);

CREATE TABLE IF NOT EXISTS rate_limits (
  key           TEXT PRIMARY KEY,
  count         INTEGER NOT NULL DEFAULT 0 CHECK (count >= 0),
  window_start  TEXT NOT NULL,
  blocked_until TEXT,
  expires_at    TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS idempotency_keys (
  key          TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users(id),
  route        TEXT NOT NULL,
  status_code  INTEGER NOT NULL,
  response_ref TEXT,
  created_at   TEXT NOT NULL,
  expires_at   TEXT NOT NULL
);

-- Seed once at migration time so a fresh database can render the sign-in page
-- before the demo data is loaded.
INSERT OR IGNORE INTO roles (key, label, description, is_system, sort_order) VALUES
  ('ADMIN',    'Admin',    'Owns access, configuration and the audit trail.', 1, 1),
  ('MANAGER',  'Manager',  'Runs customers, jobs, scheduling and invoices.',   1, 2),
  ('ENGINEER', 'Engineer', 'Field installer. Sees assigned jobs only.',         1, 3),
  ('CUSTOMER', 'Customer', 'Customer portal login for one customer record.',   1, 4);
